class Solution {
public:
    int brokenCalc(int startValue, int target) {
        long long t = target;
        long long steps = 0;
        while (t > startValue) {
            if ((t & 1LL) == 0) {
                t >>= 1;          // t = t / 2
            } else {
                ++t;              // reverse of subtract 1
            }
            ++steps;
        }
        steps += startValue - t;   // remaining subtract‑1 operations
        return static_cast<int>(steps);
    }
};

