var brokenCalc = function(startValue, target) {
    let t = target;
    let steps = 0;
    while (t > startValue) {
        if ((t & 1) === 0) {
            t = t >> 1;          // t = t / 2
        } else {
            t += 1;              // reverse of subtract 1
        }
        steps += 1;
    }
    steps += startValue - t;   // remaining subtract‑1 operations
    return steps;
};
